const items = $input.all();
const tickets = items.map(t => t.json).filter(t => t && t.ticket_id);

if (tickets.length === 0) {
  return [{ json: {
    total: 0,
    by_priority: { high: 0, medium: 0, low: 0 },
    by_category: {},
    open: 0,
    resolved: 0,
    top_category: 'None',
    date: new Date().toISOString().slice(0, 10)
  }}];
}

const summary = {
  total: tickets.length,
  by_priority: { high: 0, medium: 0, low: 0 },
  by_category: {},
  open: 0,
  resolved: 0,
  date: new Date().toISOString().slice(0, 10)
};

for (const t of tickets) {
  const p = t.priority || 'medium';
  summary.by_priority[p] = (summary.by_priority[p] || 0) + 1;
  const c = t.category || 'General';
  summary.by_category[c] = (summary.by_category[c] || 0) + 1;
  if (t.status === 'resolved') summary.resolved++;
  else summary.open++;
}

const sortedCategories = Object.entries(summary.by_category).sort((a, b) => b[1] - a[1]);
summary.top_category = sortedCategories[0]?.[0] || 'None';

return [{ json: summary }];

